def cycpattern_check(a: str, b: str) -> bool:
    """
    Checks if the second word or any of its rotations is a substring in the first word.
    """
    if a == b:
        return True
    if not b:
        return True
    for i in range(len(b)):
        rotated_b = b[i:] + b[:i]
        if rotated_b in a:
            return True
    return False
